// Normalisasi data Error Trigger untuk endpoint admin /ingestion/error.
// Hanya identitas workflow/eksekusi, node, dan pesan yang sudah diredaksi yang dikirim.
const redact = (s) => String(s)
  .replace(/(bearer\s+)[\w.\-~+/]+=*/gi, '$1[REDACTED]')
  .replace(/((?:api[_-]?key|token|secret|password|authorization)["'\s:=]+)[^\s"',]+/gi, '$1[REDACTED]');

return $input.all().map((item, index) => {
  const data = item.json ?? {};
  const execution = data.execution ?? {};
  const workflow = data.workflow ?? {};
  const trigger = data.trigger ?? {};
  const error = execution.error ?? trigger.error ?? data.error ?? {};
  const node = execution.lastNodeExecuted ?? error.node?.name ?? null;
  const rawMessage = typeof error === 'string'
    ? error
    : (error.message ?? data.message ?? 'Kesalahan workflow tidak diketahui');
  const executionId = execution.id
    ? String(execution.id)
    : `trigger-${workflow.id ?? 'unknown'}-${Date.now()}`;
  return {
    json: {
      workflow: String(workflow.name ?? 'Unknown Workflow').slice(0, 120),
      workflow_id: workflow.id ? String(workflow.id) : null,
      execution_id: executionId.slice(0, 128),
      node: node ? String(node).slice(0, 255) : null,
      message: redact(rawMessage).slice(0, 2000) || 'Kesalahan workflow tidak diketahui',
      stack: error.stack ? redact(error.stack).slice(0, 4000) : null,
      mode: execution.mode ?? trigger.mode ?? null,
      retry_of: execution.retryOf ? String(execution.retryOf) : null,
      execution_url: execution.url ?? null,
    },
    pairedItem: { item: index },
  };
});
